//! ИФМОСТРОЙ-14: функции, лямбды, Автоматрон и Босс.
use super::*;

pub(super) fn first(stages: &[Stage]) -> usize {
    stages.iter().position(|s| s.id == "if_entry").expect("if_entry missing")
}

fn node(id: &str, cases: Vec<Value>, task_override: Option<String>) -> Stage {
    let mut stage = Stage {
        label: String::new(), lore: String::new(), task: String::new(),
        kind: Encounter::GrotQuest, expected: String::new(), id: id.into(),
        node_type: String::new(), validator: String::new(),
        pep8_coef: 1.0, strokes_coef: 1.0, reward: None,
        input: String::new(), computation_required: false, text_tolerance: false,
    }.with_content();
    if let Some(task) = task_override { stage.task = task; }
    stage.input = serde_json::to_string(&cases).unwrap_or_default();
    stage
}

pub(super) fn exit() -> Stage { node("field_to_if", vec![], None) }

pub(super) fn build(seed: u64) -> Vec<Stage> {
    let _ = seed;
    let harry = vec![
        json!({"inputs":["12345"], "expected":"620448401733239439360000"}),
        json!({"inputs":["246"], "expected":""}),
        json!({"inputs":["13579"], "expected":"1"}),
        json!({"inputs":["802"], "expected":""}),
        json!({"inputs":["640"], "expected":""}),
        json!({"inputs":["10020"], "expected":"2432902008176640000"}),
    ];
    // В одном бою одно уравнение. Проверяем именно десятикратное решение.
    let eqs: [(i64,i64,i64); 4] = [(1,-5,6),(1,2,1),(2,-7,3),(1,0,-9)];
    let (a,b,c) = eqs[(seed as usize) % eqs.len()];
    let algorithms = vec![json!({"inputs":[a.to_string(),b.to_string(),c.to_string()],
        "a":a,"b":b,"c":c})];
    let algorithms_task = format!("{}\n\nТекущее уравнение: {}x² {:+}x {:+} = 0.",
        node("if_algorithms",vec![],None).task, a,b,c);
    let mimic = vec![
        json!({"inputs":["яблоко","кот","яблоко","волк","кот",""]}),
        json!({"inputs":["a","a","a",""]}),
        json!({"inputs":["one","two","three",""]}),
    ];
    vec![
        node("if_entry",vec![],None), node("if_functions",vec![],None),
        node("if_harry",harry,None), node("if_algorithms",algorithms,Some(algorithms_task)),
        node("if_fulione",vec![json!({"inputs":[]})],None),
        node("if_lambda",vec![],None), node("if_mimic",mimic,None),
        node("if_boss",vec![json!({"inputs":[]})],None),
        node("if_clear",vec![],None), node("if_to_oop",vec![],None),
    ]
}
